  bpShortLinksIntro: "సాధారణంగా పంచిన ఇన్‌వాయిస్, రసీదు లేదా అపాయింట్‌మెంట్ పూర్తిగా దాని లింక్ లోపలే వెళ్తుంది, కాబట్టి ఏదీ ఎక్కడా అప్‌లోడ్ కాదు, సిగ్నల్ లేని ఫోన్‌లోనూ లింక్ తెరుచుకుంటుంది — కానీ లింక్ కొన్ని వేల అక్షరాల పొడవు అవుతుంది.",
  bpOfferShorten: "పంచే లింక్‌ను పొట్టిగా చేసే వీలు చూపించు",
  bpOfferShortenHint: "పంచే షీట్‌లో ఒక “పొట్టిగా చేయి” బటన్ చేరుతుంది. మీరు నొక్కే వరకు ఏదీ పొట్టిగా కాదు — ఒకసారి ఒకటి.",
  bpShortenAuto: "ప్రతి లింక్‌ను తనంతట తానే పొట్టిగా చేయి",
  bpShortenAutoHint: "బటన్ అవసరం ఉండదు: పంచే షీట్ తెరిస్తేనే ఆ పత్రం అప్‌లోడ్ అయి పొట్టి లింక్ వెంటనే వస్తుంది. అది విఫలమైతే లేదా మీరు ఆఫ్‌లైన్‌లో ఉంటే, పూర్తి లింక్ వస్తుంది.",
  bpWhatChanges: "పొట్టిగా చేయడం వల్ల ఏం మారుతుంది",
  bpWhatChangesBody: "లింక్‌ను పొట్టిగా ఉంచడానికి ఆ పత్రాన్ని మా సర్వర్‌లో భద్రపరచాల్సి ఉంటుంది — పొట్టి లింక్ దాని చిరునామా మాత్రమే. ఎవరైనా చివరిసారి తెరిచిన 180 రోజుల తరువాత మేము దాన్ని తొలగిస్తాం. పత్రం ఇకపై లింక్ లోపల ఉండదు, కాబట్టి మీరు పంపిన వారికి దాన్ని తెరవడానికి ఇంటర్నెట్ కావాలి.",
  bpLeaveOff: "దీన్ని ఆపి ఉంచితే ప్రతి పంపకం పూర్తిగా తనలోనే పూర్తవుతుంది, సరిగ్గా ఇంతకుముందులాగే.",
