  bpOfferShortenHint: "મોકલવાની શીટમાં એક “ટૂંકું કરો” બટન ઉમેરાય છે. તમે દબાવો નહીં ત્યાં સુધી કંઈ ટૂંકું થતું નથી — એક સમયે એક જ.",
